The following are equivalent:
\begin{enumerate}
    \item $\cc{\Sigma_2E}^A \not\subset$ i.o.-$\cc{SIZE}^A[2^{\Omega(n)}]$ for every oracle A;
    \item for $m = 2^{\Omega(n)}$, the $\cc{MissingString}$ problem can be solved by a uniform family of size-$2^{\poly(n)}$ depth-3 $\cc{AC}^0$ circuits.
\end{enumerate}

Let $T:\N \rightarrow \N$. We say that a language $L\in \cc{S_2TIME}[T(n)]$, if there exists an $O(T(n))$-time verifier $V(x, \pi_1, \pi_2)$ that takes $x\in\bits^n$ and $\pi_1, \pi_2 \in \bits^{T(n)}$ as input, satisfying that:
\begin{itemize}
    \item if $x\in L$, then there exists $\pi_1$ such that for every $\pi_2$, \\ $V(x, \pi_1, \pi_2) = 1$, and
    \item if $x\notin L$, then there exists $\pi_2$ such that for every $\pi_1$,\\ $V(x, \pi_1, \pi_2) = 0$.
\end{itemize}
Moreover, we say $L \in \cc{S_2E}$ if $L\in \cc{S_2TIME}[T(n)]$ for some $T(n)\leq 2^{O(n)}$, and  $L \in \cc{S_2P}$ if $L\in \cc{S_2TIME}[p(n)]$ for some polynomial $p$.

A single-valued $\fsigp$ algorithm $A$ is specified by a polynomial $\ell(\cdot)$ together with a polynomial-time algorithm $V_A(x, \pi_1, \pi_2)$. On an input $x\in\bits^*$, we say that $A$ outputs $y_x \in \bits^*$, if the following hold:
\begin{enumerate}
    \item There is a $\pi_1 \in \bits^{\ell(|x|)}$ such that for every $\pi_2 \in \bits^{\ell(|x|)}$, $V_A(x,\pi_1, \pi_2)$ outputs $y_x$.
    \item For every $\pi_1 \in \bits^{\ell(|x|)}$ there is a $\pi_2 \in \bits^{\ell(|x|)}$, such that $V_A(x,\pi_1, \pi_2)$ outputs either $y_x$ or $\bot$.
\end{enumerate}

And we say that $A$ solves a search problem $\Pi$ if on any input $x$ it outputs a string $y_x$ and $y_x \in \Pi_x$.

A single-valued $\fsp$ algorithm $A$ is specified by a polynomial $\ell(\cdot)$ together with a polynomial-time algorithm $V_A(x, \pi_1, \pi_2)$. On an input $x\in\bits^*$, we say that $A$ outputs $y_x \in \bits^*$, if the following hold:
\begin{enumerate}
    \item There is a $\pi_1 \in \bits^{\ell(|x|)}$ such that for every $\pi_2 \in \bits^{\ell(|x|)}$, $V_A(x,\pi_1, \pi_2)$ outputs $y_x$.
    \item There is a $\pi_2 \in \bits^{\ell(|x|)}$ such that for every $\pi_1 \in \bits^{\ell(|x|)}$, $V_A(x,\pi_1, \pi_2)$ outputs $y_x$.
\end{enumerate}

And we say that $A$ solves a search problem $\Pi$ if on any input $x$ it outputs a string $y_x$ and $y_x \in \Pi_x$.

\label{lem:short_description}
    Let $n, T\in \N$ be such that $T = 2n \cdot 2^{2n}$. Let $C:\bits^n \rightarrow \bits^{2n}$ be a circuit, and $f\in \bits^T$. Let $h:=\cc{Histree}(C,f)$. $h$ admits a unique description $D_h$ such that:
    \begin{itemize}
        \item $|D_h| \leq O(n) \cdot \log T$.
        \item There is an algorithm $\cc{Eval}$ that takes in input $D_h$ and any vertex $(i,j)$, outputs $h(i,j)$ in time $\poly(n) \cdot \log T$.
    \end{itemize}

\label{lem:verify_history}
    Let $h := \cc{Histree}(C,f)$.
        There is an oracle algorithm $V$ with input parameter $T, n$ such that the following holds:
        \begin{enumerate}
            \item $V$ takes $\tilde{f} \in \bits^T$ as an oracle, $C$, $\widetilde{D_h}$ and $w\in \bits^{2 \log T + n}$ as inputs. It runs in $\poly(n)$ time.
            \item $D_h$ defined on $h := \cc{Histree}(C,f)$ is the unique string satisfying the following:
            \[ V^{f}(C, D_h, w) = 1, \hspace{2em} \forall w\ \in \bits^{2\log T + n} \; . \]
    \end{enumerate}

\cite[Lemma 3]{Korten}\label{lem:stretch_increase}
    Let $n\in \N$. There is a polynomial time algorithm $A$ and an $\cc{FP}^{\NP}$ algorithm $B$ such that the following holds:
    \begin{enumerate}
        \item Given a circuit $C:\bits^n \rightarrow \bits^{n+1}$, $A(C)$ outputs a circuit $D:\bits^n \rightarrow \bits^{2n}$.
        \item Given any $y\in \bits^{2n} \backslash \Im(D)$, $B(C,y)$ outputs a string $z \in \bits^{n+1} \backslash \Im(C)$.
    \end{enumerate}
